const m = /^Bearer\s+(\S+)$/i.exec(h);
const fail = (code, details) => {
  msg.statusCode = 401;
  msg.headers = { 'WWW-Authenticate': 'Bearer' };
  msg.payload = { error: code, details: details };
  return [null, msg];
};
if (!m) return fail('UNAUTHORIZED', 'กรุณาเข้าสู่ระบบ');
try {
  const d = global.get('jwt').verify(m[1], env.get('JWT_SECRET'), { algorithms: ['HS256'] });
  msg.user = { id: Number(d.sub), email: d.email };
  return [msg, null];
} catch (e) {
  if (e.name === 'TokenExpiredError') return fail('TOKEN_EXPIRED', 'เซสชันหมดอายุ กรุณาเข้าสู่ระบบใหม่');
  return fail('UNAUTHORIZED', 'โทเคนไม่ถูกต้อง กรุณาเข้าสู่ระบบใหม่');
}

