// กัน brute force: ผิดครบ 5 ครั้งใน 5 นาทีต่อ email → 429 (เก็บใน flow context ชื่อ loginFails)
const WINDOW = 5 * 60 * 1000, MAX = 5;
const b = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const email = typeof b.email === 'string' ? b.email.trim().toLowerCase() : '';
const pw = typeof b.password === 'string' ? b.password : '';
if (!email || !pw) {
  msg.statusCode = 400;
  msg.payload = { error: 'VALIDATION', details: 'กรุณากรอกอีเมลและรหัสผ่าน' };
  return [null, msg];
}
const now = Date.now();
const fails = flow.get('loginFails') || {};
for (const k of Object.keys(fails)) {
  fails[k] = fails[k].filter(t => now - t < WINDOW);
  if (!fails[k].length) delete fails[k];
}
flow.set('loginFails', fails);
const arr = fails[email] || [];
if (arr.length >= MAX) {
  const wait = Math.ceil((WINDOW - (now - arr[0])) / 1000);
  msg.statusCode = 429;
  msg.headers = { 'Retry-After': String(wait) };
  msg.payload = { error: 'TOO_MANY_ATTEMPTS', details: 'ลองเข้าสู่ระบบผิดหลายครั้งเกินไป กรุณารอประมาณ ' + Math.ceil(wait / 60) + ' นาทีแล้วลองใหม่' };
  return [null, msg];
}
msg.loginEmail = email;
