}
return [msg, null];

const svc = global.get('scanService');
const input = msg.input;
const mock = env.get('AI_MOCK') === 'true';
const model = env.get('LLM_MODEL');
msg.t0 = Date.now();
msg.deadline = msg.t0 + svc.TOTAL_BUDGET_MS;   // เวลารวมสูงสุดของคำขอนี้ (รวม retry/fallback)
msg.inputType = input.kind;
msg.imagePath = input.kind === 'image' ? svc.saveUpload(msg.user.id, input.buf, input.ext) : null;
msg.ai = { model: mock ? 'mock' : model, fallbackModel: env.get('LLM_MODEL_FALLBACK') || null, retried: false, noRetry: env.get('GEMINI_NO_RETRY') === 'true', calls: 0 };
node.log('scan start user=' + msg.user.id + ' type=' + input.kind + ' size=' + (input.kind === 'image' ? input.bytes + 'B' : input.text.length + 'ch') + ' mock=' + mock);

if (mock) {
  msg.mockText = input.kind === 'text' ? input.text : '';   // ใช้เฉพาะเลือก error จำลอง [[mock:...]] ในโหมดนี้
  delete msg.input;
  return [null, msg, null];
}
if (!env.get('LLM_API_KEY') || !model) {
  node.error('LLM_API_KEY หรือ LLM_MODEL ยังไม่ได้ตั้งค่า');
  svc.deleteUploadFile(msg.imagePath);
  msg.statusCode = 503;
  msg.payload = { error: 'AI_UNAVAILABLE', details: 'ระบบ AI ไม่ว่างชั่วคราว ลองใหม่อีกครั้งนะคะ' };
  return [null, null, msg];
}

// คำขอ generateContent (ใช้ header x-goog-api-key เท่านั้น — ห้ามใส่ key ใน URL)
msg.aiBody = svc.buildGeminiBody(input, global.get('prompts'), model);
msg.payload = msg.aiBody;
msg.url = svc.geminiUrl(model);
msg.headers = { 'x-goog-api-key': env.get('LLM_API_KEY'), 'content-type': 'application/json' };
msg.requestTimeout = svc.FIRST_TIMEOUT_MS;      // ครั้งแรก 20 วินาที ครั้งถัดไปใช้เวลาที่เหลือ
msg.t1 = Date.now();
delete msg.input;
return [msg, null, null];

const svc = global.get('scanService');
// timeout/เครือข่าย: node http request ส่ง msg ออก output เดียวกัน โดย statusCode เป็นรหัส error (string เช่น 'ETIMEDOUT') ไม่ใช่ตัวเลข
// (ไม่ใช้ catch node เพราะ http request ส่งทั้งสองทาง ทำให้ตัดสินซ้ำสองรอบ)
const status = msg.statusCode;
const errored = typeof status !== 'number';
msg.ai.calls++;
node.log('gemini_http model=' + msg.ai.model + ' call=' + msg.ai.calls + ' status=' + (errored ? 'error:' + status : status) + ' ms=' + (Date.now() - msg.t1));
if (!errored && (status < 200 || status >= 300) && msg.payload && msg.payload.error) {
  // error body ฉบับเต็ม (status, message, details[] ที่ Google ใช้บอก field ที่ผิด) — ไม่มี key/รูป/ocr_text
  node.warn('gemini error ' + status + ': ' + JSON.stringify(msg.payload.error).slice(0, 3000));
}
const step = svc.nextStep(msg.ai, status, errored, msg.deadline - Date.now());
delete msg.headers;                              // header ของ Gemini / API key ห้ามหลุดไปกับ http response

if (step.action === 'ok') return [msg, null, null];

if (step.action === 'retry') {
  // 429/5xx/timeout → สลับรุ่นสำรองทันที (ถ้าเป็นคนละรุ่น) ไม่เช่นนั้นรุ่นเดิมเว้น 2 วินาที (งบ retry = 1 ครั้ง) ; timeout ครั้งนี้ = เวลาที่เหลือของงบ 40 วินาที
  msg.ai.retried = true;
  msg.ai.model = step.model;
  msg.delay = step.delayMs;
  msg.url = svc.geminiUrl(step.model);
  msg.aiBody = svc.bodyForModel(msg.aiBody, step.model);   // thinkingLevel ต้องตรงรุ่นที่ลอง (Lite=minimal, รุ่นอื่น=low)
  msg.payload = msg.aiBody;
  msg.headers = { 'x-goog-api-key': env.get('LLM_API_KEY'), 'content-type': 'application/json' };
  msg.requestTimeout = step.timeoutMs;
  delete msg.statusCode;
  msg.t1 = Date.now() + step.delayMs;
  return [null, msg, null];
}

svc.deleteUploadFile(msg.imagePath);
node.warn('scan failed reason=' + step.reason + ' calls=' + msg.ai.calls + ' ms=' + (Date.now() - msg.t0));
msg.statusCode = 503;
msg.payload = { error: 'AI_UNAVAILABLE', details: 'ระบบ AI ไม่ว่างชั่วคราว ลองใหม่อีกครั้งนะคะ' };
