// ผลตัวอย่างจาก prompts/mock-response.json ผ่าน extract + validator จริง ; llm_model = "mock"
// ใส่ [[mock:no_result]] [[mock:invalid_json]] [[mock:schema]] [[mock:unavailable]] ในข้อความ เพื่อทดสอบการแปลง error
const hint = (/\[\[mock:(\w+)\]\]/.exec(msg.mockText || '') || [])[1];
const wrap = (text) => ({ candidates: [{ content: { parts: [{ text }] }, finishReason: 'STOP' }] });
msg.statusCode = 200;
delete msg.mockText;
if (hint === 'unavailable') {
  msg.statusCode = 503;
  msg.payload = { error: 'AI_UNAVAILABLE', details: 'ระบบ AI ไม่ว่างชั่วคราว ลองใหม่อีกครั้งนะคะ' };
  return [null, msg];
}
if (hint === 'no_result') msg.payload = { promptFeedback: { blockReason: 'SAFETY' } };
else if (hint === 'invalid_json') msg.payload = wrap('ไม่ใช่ JSON {');
else if (hint === 'schema') msg.payload = wrap('{"foo":1}');
else msg.payload = wrap(JSON.stringify(global.get('prompts').mockResponse));
return [msg, null];

const r = global.get('scanService').extractText(msg.payload);
