delete msg.headers;
msg.statusCode = 500;
msg.payload = { error: 'INTERNAL_ERROR', details: 'ระบบขัดข้อง กรุณาลองใหม่ภายหลัง' };
return msg;

// นโยบาย: เก็บรูปไม่เกิน 7 วัน (confirm/discard จะลบทันที — ทำวันที่ 5) ดู README "ความเป็นส่วนตัวของข้อมูล"
const r = await global.get('scanService').cleanupOldUploads(global.get('db'), 7);
node.log('cleanup uploads rows=' + r.rows + ' files=' + r.files + ' orphans=' + r.orphans);
msg.payload = r;
return msg;

// ไม่ใช่เจ้าของ / ไม่มีรูป / รูปถูกลบแล้ว = 404 ; ส่งไฟล์ตามจริงพร้อม Content-Type และห้ามแคช
const r = await global.get('prescriptionService').image(global.get('db'), msg.user.id, msg.req.params.id);
if (r.status !== 200) {
  delete msg.headers;
  msg.statusCode = r.status;
  msg.payload = r.body;
  return [null, msg];
}
msg.statusCode = 200;
msg.headers = { 'Content-Type': r.mime, 'Cache-Control': 'private, no-store', 'X-Content-Type-Options': 'nosniff' };
msg.payload = r.buffer;
return [msg, null];

// ตรวจ owner (404) → status ต้อง draft (409 ALREADY_DONE) → ตรวจทุก item ด้วย validate-medication (400 + item_index)
// → transaction: create/refill ทุกรายการ + status = confirmed ; พลาดตรงไหน = ROLLBACK ทั้งหมด → หลัง COMMIT ลบรูป
const r = await global.get('prescriptionService').confirm(global.get('db'), msg.user.id, msg.req.params.id, msg.payload);
msg.statusCode = r.status;
msg.payload = r.body;
return r.status === 200 ? [msg, null] : [null, msg];

// ไม่ใช่เจ้าของ = 404 ; ไม่ใช่ draft = 409 ALREADY_DONE ; สำเร็จ = status discarded + ลบไฟล์รูป
const r = await global.get('prescriptionService').discard(global.get('db'), msg.user.id, msg.req.params.id);
msg.statusCode = r.status;
msg.payload = r.body;
return r.status === 200 ? [msg, null] : [null, msg];
